import{_ as a,o,c as t,ag as i}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"UncivCN 新特性","description":"","frontmatter":{"title":"UncivCN 新特性"},"headers":[],"relativePath":"zh/UncivCN/Features.md","filePath":"zh/UncivCN/Features.md"}'),c={name:"zh/UncivCN/Features.md"};function l(n,e,r,d,s,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="uncivcn-新特性" tabindex="-1">UncivCN 新特性 <a class="header-anchor" href="#uncivcn-新特性" aria-label="Permalink to &quot;UncivCN 新特性&quot;">​</a></h1><p>本文逐项介绍 UncivCN 分支相对上游新增的功能。括号内为引入版本。</p><h2 id="lua-模组系统-4-20-8-2-起-持续增强" tabindex="-1">Lua 模组系统（4.20.8.2 起，持续增强） <a class="header-anchor" href="#lua-模组系统-4-20-8-2-起-持续增强" aria-label="Permalink to &quot;Lua 模组系统（4.20.8.2 起，持续增强）&quot;">​</a></h2><p>模组可以挂载 Lua 脚本，实现远超纯 JSON 的复杂逻辑：</p><ul><li><strong>触发方式</strong>：<code>TriggerLuaFunction</code> unique（建筑/科技/政策/时代/事件/单位/全局词条）与游戏生命周期钩子（<code>&lt;upon turn start&gt;</code> 等）</li><li><strong>ctx 上下文对象</strong>：脚本内可访问 <code>civ</code>（文明）、<code>city</code>（城市）、<code>unit</code>（单位）、<code>tile</code>（地块）、<code>game</code>（全局）等 API，另有 <code>ctx.parameter</code>（Countable 解析）、<code>ctx.store</code>（持久化存储）、<code>ctx.count</code> / <code>ctx.evaluateConditional</code></li><li><strong>安全保障</strong>：加固的沙箱（无 <code>io</code>/<code>os</code>/<code>luajava</code>/<code>package</code> 逃逸路径，移除 <code>string.dump</code>）+ 每次脚本加载与函数调用的指令预算，死循环无法卡死游戏</li><li><strong>错误报告</strong>：运行时错误向玩家弹出时带脚本名与行号；AI 回合触发的错误记入模组检查器，不再丢失</li><li><strong>工具链</strong>：游戏内模组检查器与 <code>mod-ci</code> 命令行检查 Lua 语法、函数引用与 API 拼写（带建议）；自动生成的 EmmyLua 类型定义（<code>docs/Modders/lua-api.lua</code>）为 LuaLS 系编辑器提供自动补全与悬停文档；起步模板（<code>docs/Modders/examples/LuaStarterMod/</code>）几分钟即可上手；另有 <code>game.findTiles</code> 等便捷 API</li></ul><p>完整教程见 <a href="/Unciv/zh/Modders/Lua-Modding.html">Lua 脚本</a>。</p><h2 id="镜像与环形地图-4-20-7-3-4-20-7-4-4-21-0-起" tabindex="-1">镜像与环形地图（4.20.7.3 / 4.20.7.4 / 4.21.0 起） <a class="header-anchor" href="#镜像与环形地图-4-20-7-3-4-20-7-4-4-21-0-起" aria-label="Permalink to &quot;镜像与环形地图（4.20.7.3 / 4.20.7.4 / 4.21.0 起）&quot;">​</a></h2><ul><li><strong>三种镜像地图模式</strong>：创建游戏时可选，镜像模式下资源也对称分布（4.20.7.4）</li><li><strong>环形地图</strong>：地图首尾相接，取消旋转对称地图对半径的奇偶限制（4.20.17.2）</li></ul><h2 id="单位钉-地图钉-4-20-17-2" tabindex="-1">单位钉 / 地图钉（4.20.17.2） <a class="header-anchor" href="#单位钉-地图钉-4-20-17-2" aria-label="Permalink to &quot;单位钉 / 地图钉（4.20.17.2）&quot;">​</a></h2><p>在世界屏幕右下角小地图左侧新增两个独立开关：</p><ul><li><strong>单位钉</strong>：开启后可点击任意单位（含他国单位）添加备注，备注显示在单位兵棋正下方；再次点击可编辑或删除；同一地块多单位时弹出选择列表</li><li><strong>地图钉</strong>：可点击任意地块（含无单位地块）添加备注，显示在地块上，优先级高于食物/产能/金币等产出图标</li></ul><p><strong>编辑方式（4.21.6.1）</strong>——无需开关，普通点击永不被劫持：</p><ul><li>手机：长按地块/单位编辑其备注（未选中单位时；已选中单位时长按仍为移动单位，行为不变）</li><li>桌面：Alt+点击地块/单位编辑其备注</li><li>开关仍保留作为备选：开启后普通点击即编辑（兼容旧习惯）</li></ul><p><strong>显示（4.21.6.1）</strong>：备注气泡截断为 8 字符，不再遮挡地图；点击气泡可查看全文并支持编辑/删除（手机无悬停，以点击替代）。地块笔记开关改用星标图标，两个开关在桌面端悬停有文字提示。</p><p>备注数据保存在 <code>{存档名}_notes</code> 文件中。</p><h2 id="地块归属-tile-claim-4-21-0-合并上游前自研-持续维护" tabindex="-1">地块归属 tile-claim（4.21.0 合并上游前自研，持续维护） <a class="header-anchor" href="#地块归属-tile-claim-4-21-0-合并上游前自研-持续维护" aria-label="Permalink to &quot;地块归属 tile-claim（4.21.0 合并上游前自研，持续维护）&quot;">​</a></h2><p>城市可对周边地块宣称归属（Claim）并交换地块，相关功能随上游演进持续适配。 自 4.21.6.1 起，内置基础规则集（Vanilla / Gods &amp; Kings）不再默认启用该特性——由模组通过 ModOptions 的 <code>&quot;Allow cities to claim tiles&quot;</code> unique 自行声明启用（如 CoeHarMod）。</p><h2 id="人口自动锁定按钮-4-21-0-1" tabindex="-1">人口自动锁定按钮（4.21.0.1） <a class="header-anchor" href="#人口自动锁定按钮-4-21-0-1" aria-label="Permalink to &quot;人口自动锁定按钮（4.21.0.1）&quot;">​</a></h2><p>城市屏幕右下角新增 <strong>自动锁定</strong> 按钮，可<strong>永久切换</strong>「不锁人口 / 锁人口」两种工作地块分配策略，替代原版每次手动锁定的快捷方式。</p><h2 id="随机数读档可变性-4-21-0-1" tabindex="-1">随机数读档可变性（4.21.0.1） <a class="header-anchor" href="#随机数读档可变性-4-21-0-1" aria-label="Permalink to &quot;随机数读档可变性（4.21.0.1）&quot;">​</a></h2><p>单机模式下读档后随机数序列可变（不再固定），4.21.0.1 起该功能<strong>联机时不可用</strong>，保证多人对局公平性。</p><h2 id="新建游戏设置导出-导入剪贴板-4-21-5-1" tabindex="-1">新建游戏设置导出 / 导入剪贴板（4.21.5.1） <a class="header-anchor" href="#新建游戏设置导出-导入剪贴板-4-21-5-1" aria-label="Permalink to &quot;新建游戏设置导出 / 导入剪贴板（4.21.5.1）&quot;">​</a></h2><p>新建游戏时可将当前全部设置复制到剪贴板，或从剪贴板粘贴恢复，方便分享开局配置。</p><h2 id="轮询联机-4-20-8-1" tabindex="-1">轮询联机（4.20.8.1） <a class="header-anchor" href="#轮询联机-4-20-8-1" aria-label="Permalink to &quot;轮询联机（4.20.8.1）&quot;">​</a></h2><p>在动态回合基础上新增<strong>轮询联机</strong>模式：同一回合拆分为固定时长的时间片，玩家间按时间片轮流传递存档，将等待上限从「对手想多久就多久」压缩为数秒。</p><ul><li>创建游戏时勾选 Online Multiplayer 后可选 Polling interval（Off / 5s / 10s / 15s / 20s / 30s）</li><li>可查看其他玩家的在线状态（4.20.8.4）</li></ul><p>完整机制见 <a href="./Polling-multiplayer.html">轮询联机机制</a>。</p><h2 id="默认服务器-4-21-0-1" tabindex="-1">默认服务器（4.21.0.1） <a class="header-anchor" href="#默认服务器-4-21-0-1" aria-label="Permalink to &quot;默认服务器（4.21.0.1）&quot;">​</a></h2><p>联机默认服务器改为 <code>http://sp.unciv.cn:30123</code>。</p><h2 id="游戏版本兼容性隔离-4-20-17-2" tabindex="-1">游戏版本兼容性隔离（4.20.17.2） <a class="header-anchor" href="#游戏版本兼容性隔离-4-20-17-2" aria-label="Permalink to &quot;游戏版本兼容性隔离（4.20.17.2）&quot;">​</a></h2><p>旧版客户端无法加载新版存档，避免版本混用导致的存档损坏。</p><h2 id="mergeaction-扩展-json-系统-4-20-7-3" tabindex="-1">MergeAction 扩展 JSON 系统（4.20.7.3） <a class="header-anchor" href="#mergeaction-扩展-json-系统-4-20-7-3" aria-label="Permalink to &quot;MergeAction 扩展 JSON 系统（4.20.7.3）&quot;">​</a></h2><p>在原版基础上扩展 <code>_mergeAction</code>（字段级合并）能力，模组可增量修改规则集对象而不必整对象替换。 另有多个新增 Countables 参数类型、Amount 参数兼容 Countables（4.20.8.2）。</p><p>教程见 <a href="/Unciv/zh/Modders/Mod-file-structure/6-MergeActions.html">UncivCN 扩展 JSON - MergeAction 教程</a>。</p><h2 id="模组版本要求-4-21-6-1" tabindex="-1">模组版本要求（4.21.6.1） <a class="header-anchor" href="#模组版本要求-4-21-6-1" aria-label="Permalink to &quot;模组版本要求（4.21.6.1）&quot;">​</a></h2><p>模组可在 <code>ModOptions.json</code> 中声明版本号与兼容性要求，仅以警告方式检查（不阻止）：</p><ul><li><code>modVersion</code>：格式 <code>n.n.n</code>，不填默认 <code>0.0.1</code>，显示在模组管理器中</li><li><code>gameVersionRange</code>：该模组可应用的游戏版本范围，<code>min~max</code>（闭区间，<code>n.n.n.n</code> 可带 <code>-patchN</code> 后缀，任一侧可省略）；不填默认全版本可用</li><li><code>modDependencies</code>：依赖模组及其精确/范围版本要求；依赖缺失或版本不满足时给出警告</li></ul><p>警告出现在模组管理器（警告标记 + 信息面板）、新建游戏模组选择、以及模组检查器（选项 → 定位模组错误）中。</p><p>对玩家：警告仅表示模组在当前游戏版本或当前模组组合下可能无法按预期工作——模组仍可使用。 模组作者：完整的版本格式细节与示例见 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#版本要求-uncivcn">ModOptions.json 版本要求</a>。</p><h2 id="历史-自带-uccc-模组-4-21-0-1-→-4-21-5-1-撤销" tabindex="-1">历史：自带 UCCC 模组（4.21.0.1 → 4.21.5.1 撤销） <a class="header-anchor" href="#历史-自带-uccc-模组-4-21-0-1-→-4-21-5-1-撤销" aria-label="Permalink to &quot;历史：自带 UCCC 模组（4.21.0.1 → 4.21.5.1 撤销）&quot;">​</a></h2><p>4.21.0.1 曾随游戏本体打包 UCCC 模组；4.21.5.1 起撤销该改动，游戏本体不再打包任何模组，模组需另行下载。</p>',41)])])}const g=a(c,[["render",l]]);export{p as __pageData,g as default};
